// Modified for Aomi: replies come from `aomi_sdk::http`, whole and buffered.

//! Runtime for clients generated by `aomi-build gen-client`.
//!
//! A generated method builds its request with `aomi_sdk::http`, sends it
//! through the host and decodes the reply here. The host has already read the
//! whole body, so decoding is synchronous. Every [`ResponseValue`], including
//! one inside [`Error::ErrorResponse`], keeps the reply's status, headers and
//! host record number.

#![deny(missing_docs)]

use std::ops::{Deref, DerefMut};

use aomi_sdk::http::{HeaderMap, Response};
use serde::{Serialize, de::DeserializeOwned, ser::SerializeStruct};

/// Implemented by every generated client.
pub trait ClientInfo {
    /// The version of this API, taken from the source OpenAPI document. It is
    /// sent as the `api-version` header.
    fn api_version() -> &'static str;

    /// The base URL requests are made to.
    fn baseurl(&self) -> &str;
}

/// Typed value returned by generated client methods.
///
/// This is used for successful responses and may appear in error responses
/// generated from the server (see [`Error::ErrorResponse`]).
pub struct ResponseValue<T> {
    inner: T,
    status: u16,
    headers: HeaderMap,
    record: aomi_sdk::Result<u32>,
}

impl<T: DeserializeOwned> ResponseValue<T> {
    #[doc(hidden)]
    // The error carries the whole reply, by design.
    #[allow(clippy::result_large_err)]
    pub fn from_response<E>(response: Response) -> Result<Self, Error<E>> {
        match response.json() {
            Ok(inner) => Ok(Self::new(inner, &response)),
            Err(e) => Err(Error::InvalidResponsePayload(response, e)),
        }
    }
}

impl ResponseValue<Vec<u8>> {
    #[doc(hidden)]
    pub fn raw(response: Response) -> Self {
        Self::new(response.bytes().to_vec(), &response)
    }
}

impl ResponseValue<()> {
    #[doc(hidden)]
    pub fn empty(response: Response) -> Self {
        Self::new((), &response)
    }
}

impl<T> ResponseValue<T> {
    /// A value with the status, headers and record number of `response`.
    pub fn new(inner: T, response: &Response) -> Self {
        Self {
            inner,
            status: response.status(),
            headers: response.headers().clone(),
            record: response.record(),
        }
    }

    /// Consumes the ResponseValue, returning the wrapped value. Read
    /// [`Self::record`] first when the reply is evidence.
    pub fn into_inner(self) -> T {
        self.inner
    }

    /// The HTTP status of the reply.
    pub fn status(&self) -> u16 {
        self.status
    }

    /// The headers of the reply.
    pub fn headers(&self) -> &HeaderMap {
        &self.headers
    }

    /// The host's record number for the reply, as
    /// [`aomi_sdk::http::Response::record`] reads it.
    pub fn record(&self) -> aomi_sdk::Result<u32> {
        self.record.clone()
    }

    #[doc(hidden)]
    pub fn map<U, F>(self, f: F) -> ResponseValue<U>
    where
        F: FnOnce(T) -> U,
    {
        ResponseValue {
            inner: f(self.inner),
            status: self.status,
            headers: self.headers,
            record: self.record,
        }
    }
}

impl<T> Deref for ResponseValue<T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        &self.inner
    }
}

impl<T> DerefMut for ResponseValue<T> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.inner
    }
}

impl<T> AsRef<T> for ResponseValue<T> {
    fn as_ref(&self) -> &T {
        &self.inner
    }
}

impl<T: std::fmt::Debug> std::fmt::Debug for ResponseValue<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.inner.fmt(f)
    }
}

/// Error produced by generated client methods.
///
/// The type parameter is the documented error body; it is the unit type if
/// the operation documents none. Formatting it never prints headers or a raw
/// body, so a credential echoed by an API stays out of logs and model text.
pub enum Error<E = ()> {
    /// The request did not leave the sandbox: an invalid query, header or
    /// body, a host outside `[network] hosts`, or a transport failure.
    CommunicationError(aomi_sdk::Error),

    /// A documented error response.
    ErrorResponse(ResponseValue<E>),

    /// A documented response whose JSON body did not decode.
    InvalidResponsePayload(Response, aomi_sdk::Error),

    /// A response the API description does not list.
    UnexpectedResponse(Response),
}

impl<E> Error<E> {
    /// The HTTP status, if the error carries a reply.
    pub fn status(&self) -> Option<u16> {
        match self {
            Error::CommunicationError(_) => None,
            Error::ErrorResponse(rv) => Some(rv.status()),
            Error::InvalidResponsePayload(r, _) | Error::UnexpectedResponse(r) => Some(r.status()),
        }
    }

    /// Converts this error into one without a typed body.
    pub fn into_untyped(self) -> Error {
        match self {
            Error::CommunicationError(e) => Error::CommunicationError(e),
            Error::ErrorResponse(rv) => Error::ErrorResponse(rv.map(|_| ())),
            Error::InvalidResponsePayload(r, e) => Error::InvalidResponsePayload(r, e),
            Error::UnexpectedResponse(r) => Error::UnexpectedResponse(r),
        }
    }
}

impl<E> From<aomi_sdk::Error> for Error<E> {
    fn from(e: aomi_sdk::Error) -> Self {
        Self::CommunicationError(e)
    }
}

impl<E: std::fmt::Debug> std::fmt::Display for Error<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::CommunicationError(e) => write!(f, "[{}] {}", e.code, e.message),
            Error::ErrorResponse(rv) => write!(f, "status {}: {:?}", rv.status, rv.inner),
            Error::InvalidResponsePayload(r, e) => write!(
                f,
                "status {}: invalid {}-byte payload: {}",
                r.status(),
                r.bytes().len(),
                e.message
            ),
            Error::UnexpectedResponse(r) => write!(f, "unexpected status {}", r.status()),
        }
    }
}

impl<E: std::fmt::Debug> std::fmt::Debug for Error<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(self, f)
    }
}

impl<E: std::fmt::Debug> std::error::Error for Error<E> {}

/// A tool returns an [`aomi_sdk::Error`]; `?` on a generated call converts.
/// A transport error keeps its code; a reply becomes `http_status` or
/// `invalid_json`.
impl<E: std::fmt::Debug> From<Error<E>> for aomi_sdk::Error {
    fn from(e: Error<E>) -> Self {
        match e {
            Error::CommunicationError(e) => e,
            Error::InvalidResponsePayload(..) => aomi_sdk::err("invalid_json", e.to_string()),
            Error::ErrorResponse(_) | Error::UnexpectedResponse(_) => {
                aomi_sdk::err("http_status", e.to_string())
            }
        }
    }
}

// See https://url.spec.whatwg.org/#url-path-segment-string
const PATH_SET: &percent_encoding::AsciiSet = &percent_encoding::CONTROLS
    .add(b' ')
    .add(b'"')
    .add(b'#')
    .add(b'<')
    .add(b'>')
    .add(b'?')
    .add(b'`')
    .add(b'{')
    .add(b'}')
    .add(b'/')
    .add(b'%');

#[doc(hidden)]
/// Percent encode input string.
pub fn encode_path(pc: &str) -> String {
    percent_encoding::utf8_percent_encode(pc, PATH_SET).to_string()
}

#[doc(hidden)]
pub struct QueryParam<'a, T> {
    name: &'a str,
    value: &'a T,
}

impl<'a, T> QueryParam<'a, T> {
    #[doc(hidden)]
    pub fn new(name: &'a str, value: &'a T) -> Self {
        Self { name, value }
    }
}
impl<T> Serialize for QueryParam<'_, T>
where
    T: Serialize,
{
    fn serialize<S>(&self, inner: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let serializer = QuerySerializer {
            inner,
            name: self.name,
        };
        self.value.serialize(serializer)
    }
}

pub(crate) struct QuerySerializer<'a, S> {
    inner: S,
    name: &'a str,
}

macro_rules! serialize_scalar {
    ($f:ident, $t:ty) => {
        fn $f(self, v: $t) -> Result<Self::Ok, Self::Error> {
            [(self.name, v)].serialize(self.inner)
        }
    };
}

impl<'a, S> serde::Serializer for QuerySerializer<'a, S>
where
    S: serde::Serializer,
{
    type Ok = S::Ok;
    type Error = S::Error;
    type SerializeSeq = QuerySeq<'a, S::SerializeSeq>;
    type SerializeTuple = S::SerializeTuple;
    type SerializeTupleStruct = S::SerializeTupleStruct;
    type SerializeTupleVariant = S::SerializeTupleVariant;
    type SerializeMap = S::SerializeMap;
    type SerializeStruct = S::SerializeStruct;
    type SerializeStructVariant = S::SerializeStructVariant;

    serialize_scalar!(serialize_bool, bool);
    serialize_scalar!(serialize_i8, i8);
    serialize_scalar!(serialize_i16, i16);
    serialize_scalar!(serialize_i32, i32);
    serialize_scalar!(serialize_i64, i64);
    serialize_scalar!(serialize_u8, u8);
    serialize_scalar!(serialize_u16, u16);
    serialize_scalar!(serialize_u32, u32);
    serialize_scalar!(serialize_u64, u64);
    serialize_scalar!(serialize_f32, f32);
    serialize_scalar!(serialize_f64, f64);
    serialize_scalar!(serialize_char, char);
    serialize_scalar!(serialize_str, &str);

    fn serialize_bytes(self, v: &[u8]) -> Result<Self::Ok, Self::Error> {
        self.inner.serialize_bytes(v)
    }

    fn serialize_none(self) -> Result<Self::Ok, Self::Error> {
        self.inner.serialize_none()
    }

    fn serialize_some<T>(self, value: &T) -> Result<Self::Ok, Self::Error>
    where
        T: ?Sized + Serialize,
    {
        // Serialize the value through self which will proxy into the inner
        // Serializer as appropriate.
        value.serialize(self)
    }

    fn serialize_unit(self) -> Result<Self::Ok, Self::Error> {
        self.inner.serialize_unit()
    }

    fn serialize_unit_struct(self, name: &'static str) -> Result<Self::Ok, Self::Error> {
        self.inner.serialize_unit_struct(name)
    }

    fn serialize_unit_variant(
        self,
        _name: &'static str,
        _variant_index: u32,
        variant: &'static str,
    ) -> Result<Self::Ok, Self::Error> {
        // A query parameter with a list of enumerated values will produce an
        // enum with unit variants. We treat these as scalar values, ignoring
        // the unit variant wrapper.
        variant.serialize(self)
    }

    fn serialize_newtype_struct<T>(
        self,
        name: &'static str,
        value: &T,
    ) -> Result<Self::Ok, Self::Error>
    where
        T: ?Sized + Serialize,
    {
        self.inner.serialize_newtype_struct(name, value)
    }

    fn serialize_newtype_variant<T>(
        self,
        name: &'static str,
        _variant_index: u32,
        variant: &'static str,
        value: &T,
    ) -> Result<Self::Ok, Self::Error>
    where
        T: ?Sized + Serialize,
    {
        // As with serde_json, we treat a newtype variant like a struct with a
        // single field. This may seem a little weird, but if an OpenAPI
        // document were to specify a query parameter whose schema was a oneOf
        // whose elements were objects with a single field, the user would end
        // up with an enum like this as a parameter.
        let mut map = self.inner.serialize_struct(name, 1)?;
        map.serialize_field(variant, value)?;
        map.end()
    }

    fn serialize_seq(self, len: Option<usize>) -> Result<Self::SerializeSeq, Self::Error> {
        let Self { inner, name, .. } = self;
        Ok(QuerySeq {
            inner: inner.serialize_seq(len)?,
            name,
        })
    }

    fn serialize_tuple(self, len: usize) -> Result<Self::SerializeTuple, Self::Error> {
        self.inner.serialize_tuple(len)
    }

    fn serialize_tuple_struct(
        self,
        name: &'static str,
        len: usize,
    ) -> Result<Self::SerializeTupleStruct, Self::Error> {
        self.inner.serialize_tuple_struct(name, len)
    }

    fn serialize_tuple_variant(
        self,
        name: &'static str,
        variant_index: u32,
        variant: &'static str,
        len: usize,
    ) -> Result<Self::SerializeTupleVariant, Self::Error> {
        self.inner
            .serialize_tuple_variant(name, variant_index, variant, len)
    }

    fn serialize_map(self, len: Option<usize>) -> Result<Self::SerializeMap, Self::Error> {
        self.inner.serialize_map(len)
    }

    fn serialize_struct(
        self,
        name: &'static str,
        len: usize,
    ) -> Result<Self::SerializeStruct, Self::Error> {
        self.inner.serialize_struct(name, len)
    }

    fn serialize_struct_variant(
        self,
        name: &'static str,
        variant_index: u32,
        variant: &'static str,
        len: usize,
    ) -> Result<Self::SerializeStructVariant, Self::Error> {
        self.inner
            .serialize_struct_variant(name, variant_index, variant, len)
    }
}

#[doc(hidden)]
pub struct QuerySeq<'a, S> {
    inner: S,
    name: &'a str,
}

impl<S> serde::ser::SerializeSeq for QuerySeq<'_, S>
where
    S: serde::ser::SerializeSeq,
{
    type Ok = S::Ok;

    type Error = S::Error;

    fn serialize_element<T>(&mut self, value: &T) -> Result<(), Self::Error>
    where
        T: ?Sized + Serialize,
    {
        let v = (self.name, value);
        self.inner.serialize_element(&v)
    }

    fn end(self) -> Result<Self::Ok, Self::Error> {
        self.inner.end()
    }
}

#[cfg(test)]
mod tests {
    use aomi_sdk::testing::reply;
    use serde::Deserialize;

    use super::*;

    #[derive(Debug, Deserialize, PartialEq)]
    struct Chain {
        id: u64,
    }

    /// `aomi_sdk::http::RequestBuilder::query` encodes each param like this.
    fn query<T: Serialize>(name: &str, value: &T) -> String {
        serde_urlencoded::to_string(QueryParam::new(name, value)).unwrap()
    }

    #[test]
    fn decoding_keeps_status_headers_and_record() {
        let ok = reply(200, &[("aomi-record", "7")], r#"{"id":1}"#);
        let value = ResponseValue::<Chain>::from_response::<()>(ok).unwrap();
        assert_eq!((value.status(), value.record().unwrap()), (200, 7));
        assert_eq!(value.id, 1);
        let mapped = value.map(|c| c.id + 1);
        assert_eq!((*mapped, mapped.record().unwrap()), (2, 7));

        let raw = ResponseValue::raw(reply(200, &[("aomi-record", "8")], "a,b\n"));
        assert_eq!((raw.record().unwrap(), raw.as_slice()), (8, &b"a,b\n"[..]));

        let empty = ResponseValue::empty(reply(204, &[("aomi-record", "9")], ""));
        assert_eq!((empty.status(), empty.record().unwrap()), (204, 9));

        let unrecorded = ResponseValue::empty(reply(204, &[], ""));
        assert_eq!(unrecorded.record().unwrap_err().code, "evidence_missing");
    }

    #[test]
    fn error_replies_keep_their_record_and_stay_sanitized() {
        let reply = reply(
            400,
            &[("aomi-record", "4"), ("set-cookie", "s=secret")],
            r#"{"id":9}"#,
        );
        let e = Error::ErrorResponse(ResponseValue::<Chain>::from_response::<()>(reply).unwrap());
        assert_eq!(e.status(), Some(400));
        let Error::ErrorResponse(rv) = &e else {
            unreachable!()
        };
        assert_eq!(rv.record().unwrap(), 4);
        assert_eq!(e.to_string(), "status 400: Chain { id: 9 }");
        let e: aomi_sdk::Error = e.into();
        assert_eq!(e.code, "http_status");

        let bad = ResponseValue::<Chain>::from_response::<()>(reply_with_body("tok=secret"));
        let e = bad.unwrap_err();
        assert!(
            e.to_string()
                .starts_with("status 200: invalid 10-byte payload")
        );
        assert!(!e.to_string().contains("secret"));
        assert_eq!(aomi_sdk::Error::from(e).code, "invalid_json");

        let e = Error::<()>::UnexpectedResponse(reply_with_body("secret"));
        assert_eq!(e.to_string(), "unexpected status 200");
    }

    fn reply_with_body(body: &str) -> Response {
        reply(200, &[], body)
    }

    #[test]
    fn query_params_omit_none_repeat_arrays_and_flatten_enums() {
        #[derive(Serialize)]
        #[serde(rename_all = "lowercase")]
        enum Kind {
            Evm,
        }
        assert_eq!(query("skip", &None::<u64>), "");
        assert_eq!(query("chainId", &Some(5u64)), "chainId=5");
        assert_eq!(query("token", &vec!["a b", "c&d"]), "token=a+b&token=c%26d");
        assert_eq!(query("kind", &Kind::Evm), "kind=evm");
    }

    #[test]
    fn path_segments_are_encoded() {
        assert_eq!(encode_path("a/b c?%"), "a%2Fb%20c%3F%25");
    }
}
